<?php namespace App\Services; use App\Models\Product; use App\Models\ProductVariant; use Illuminate\Support\Facades\Session;
class CartService { public function items():array{return Session::get('cart',[]);} public function add(Product $p,int $qty=1,?ProductVariant $v=null,array $options=[]):void{$key=$p->id.':'.($v?->id??0).':'.md5(json_encode($options));$cart=$this->items();$price=$v?->price??$p->price;$cart[$key]=['key'=>$key,'product_id'=>$p->id,'variant_id'=>$v?->id,'name'=>$p->name,'sku'=>$v?->sku??$p->sku,'price'=>(float)$price,'quantity'=>($cart[$key]['quantity']??0)+max(1,$qty),'image'=>$v?->image??$p->image,'options'=>$options];Session::put('cart',$cart);} public function update(string $key,int $qty):void{$c=$this->items(); if(isset($c[$key])){ if($qty<=0){ unset($c[$key]); } else { $c[$key]['quantity']=$qty; } Session::put('cart',$c); }} public function remove(string $key):void{$c=$this->items();unset($c[$key]);Session::put('cart',$c);} public function clear():void{Session::forget('cart');} public function subtotal():float{return array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$this->items()));} public function count():int{return array_sum(array_column($this->items(),'quantity'));} }
